import '@kerfjs/ui/layout.css';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret } from '@kerfjs/ui/token-search-field';
import { delegate } from './events';
import './search.css';

type FieldProps = Parameters<typeof TokenSearchField>[0];
type Token = NonNullable<FieldProps['tokens']>[number];
type Query = ReturnType<typeof readTokenSearchField>;
// This small application adapter supplies the package's token records, parser, suggestions,
// and field props. It must assign search-clear/search-edit/search-remove actions and token ids.
type SearchApplication = {
  initialTokens: Token[];
  fieldProps(tokens: Token[], text: string): FieldProps;
  tokenId(token: Token): string;
  editToken(token: Token): Promise<Token | null>;
  suggest(query: Query): void;
  run(query: Query): Promise<number>;
  freeText(query: Query): string;
};
export function createSearch(root: HTMLElement, paint: (html: ReturnType<typeof TokenSearchField>) => void, app: SearchApplication) {
  let tokens = [...app.initialTokens];
  let text = '';
  let disposed = false;
  let request = 0;
  const editor = () => root.querySelector<HTMLElement>('.kui-token-search__editor')!;
  const status = () => root.querySelector<HTMLElement>('[data-search-status]')!;
  const render = () => <section class="app-root kui-layout kui-section-stack">
    <TokenSearchField {...app.fieldProps(tokens, text)} tokens={tokens} />
    <p data-search-status="" role="status" aria-live="polite"></p>
  </section>;
  async function execute() {
    const current = ++request;
    status().textContent = 'Searching';
    try { const count = await app.run(readTokenSearchField(editor())); if (!disposed && current === request) status().textContent = count + (count === 1 ? ' result' : ' results'); }
    catch { if (!disposed && current === request) status().textContent = 'Search failed. Press Enter to retry.'; }
  }
  function replace(next: Token[], nextText = text) {
    tokens = next; text = nextText;
    paint(render());
    placeTokenSearchCaret(editor());
  }
  const offInput = delegate(root, 'input', '.kui-token-search__editor', () => {
    const query = readTokenSearchField(editor());
    // No render during browser text editing: selection, IME, and free text remain DOM-owned.
    text = app.freeText(query);
    app.suggest(query);
  });
  const offKey = delegate(root, 'keydown', '.kui-token-search__editor', (_, event) => {
    const keyboard = event as KeyboardEvent;
    if (keyboard.key === 'Enter' && !keyboard.isComposing) { keyboard.preventDefault(); void execute(); }
  });
  const offActions = delegate(root, 'click', '[data-action]', async element => {
    const action = element.dataset.action;
    if (action === 'search-clear') {
      editor().textContent = '';
      replace([], '');
      app.suggest(readTokenSearchField(editor()));
      status().textContent = 'Search cleared';
    } else if (action === 'search-remove' || action === 'search-edit') {
      const id = element.dataset.tokenId;
      const index = tokens.findIndex(token => app.tokenId(token) === id);
      if (index < 0) return;
      const saved = readTokenSearchField(editor());
      text = app.freeText(saved);
      if (action === 'search-remove') replace(tokens.filter((_, position) => position !== index), text);
      else {
        const replacement = await app.editToken(tokens[index]!);
        if (disposed || !replacement) return;
        replace(tokens.map((token, position) => position === index ? replacement : token), text);
      }
      status().textContent = action === 'search-remove' ? 'Filter removed' : 'Filter updated';
    }
  });
  paint(render());
  return {
    render,
    replaceTokens(next: Token[], freeText: string) { replace(next, freeText); },
    dispose() { disposed = true; request++; offInput(); offKey(); offActions(); }
  };
}
// fieldProps must name the searchbox (for example label: 'Search tasks'), and give each
// edit/remove and clear control an accessible name. app.editToken owns accessible editing
// UI and returns focus here after acceptance. Parsing and suggestions remain application-owned.

